-- ######################## A272E-05 Auswahl der Systemgruppe ########################
-- system_group
update public.fields set verification_status='verified_against_standard', verification_quote='Table 1: Subdivision of wastewater infrastructure systems into system groups | "One material flow" system & no separation of material flows, combined drainage & wastewater | „Two material flows” system & separate collection of grey- and blackwater & greywater, blackwater | „Two material flows“ system (UDT) & separate collection of urine or yellowwater and combined drainage of other partial streams & urine or yellowwater, mixture of brownand greywater | „Three material flows" system (UDT) & separate collection of urine or yellowwater, brown-and greywater & urine or yellowwater, brownwater, greywater | „Two material flows” system (dry toilet) & separate collection of greywater and faecal matter & greywater, faecal matter | „Three material flows" system (UDDT) & separate collection of urine and faeces as well as greywater & urine, faeces, greywater — printed p.11', verification_note='md-verified 2026-09-05 (§4.2 Table 1, printed p.11) [VC]', verified_at=now() where id='b72c1e70-1584-4a3b-b001-7de8ece2ec48' and verification_status not in ('verified_against_standard','corrected');
-- separation_at_source
update public.fields set verification_status='verified_against_standard', verification_quote='The overall objectives of NASS are the recycling of resources and the best possible closure of material and water loops. NASS is therefore based on the separate collection of domestic/municipal material flows directly at the point of origin. — printed p.9', verification_note='md-verified 2026-09-05 (§4.1, printed p.9) [VC]', verified_at=now() where id='64fe6d65-3868-4546-bf69-055a46641fac' and verification_status not in ('verified_against_standard','corrected');
-- urine_diverted
update public.fields set verification_status='verified_against_standard', verification_quote='In the „two material flows“ system (urine diverting toilet - UDT, no-mix toilet), yellowwater or urine is collected and treated separately frombrown and greywater. Because of the low volume flow and high nutrient content of urine, the system is characterized by a high nutrient recovery potential. — printed p.10', verification_note='md-verified 2026-09-05 (§4.2, printed p.10) [VC]', verified_at=now() where id='129d1c01-bd4e-4702-85a0-1b87d91fb56b' and verification_status not in ('verified_against_standard','corrected');
-- brown_grey_separated
update public.fields set verification_status='verified_against_standard', verification_quote='A characteristic feature of the „three material flows“ system (UDT) is also the diversion of yellowwater or urine from the remaining domestic/municipal wastewater. In addition to this, brown- and greywater are also collected separately. — printed p.10', verification_note='md-verified 2026-09-05 (§4.2, printed p.10) [VC]', verified_at=now() where id='1cd29c79-558d-4bce-939b-96903f455788' and verification_status not in ('verified_against_standard','corrected');
-- dry_toilet_used
update public.fields set verification_status='verified_against_standard', verification_quote='The „two material flows“ system (dry toilet) is similar to the blackwater system based on a separation of greywater. The difference lies in the toilet technology used: dispensing with flushing water produces undiluted faecal matter instead of blackwater. — printed p.11', verification_note='md-verified 2026-09-05 (§4.2, printed p.11) [VC]', verified_at=now() where id='966aee6d-9836-400f-a955-b08e1174862b' and verification_status not in ('verified_against_standard','corrected');
-- uddt_used
