-- primary_objective
update public.fields set verification_status='verified_against_standard', verification_quote='By deciding on a system and the associated collection and treatment of different material flows, different goals and varyingly extensive goals can be pursued in individual cases, such as: I targeted recycling of nutrients to agriculture/production of fertilizers, I generating energy by extracting biogas and/or using excess waste heat, I elimination of problematic micropollutants in high strength, separate collected wastewater streams, I meeting hygienic requirements, I compliance with increased demands on water quality in the environment, I reducing drinking water demand through the efficient use of water and utilization of the treated wastewater for various uses — printed p.9', verification_note='md-verified 2026-09-05 (§4.1, printed p.9) [VC]', verified_at=now() where id='25ff4205-507b-45c8-ad5e-e67cedec14c4' and verification_status not in ('verified_against_standard','corrected');
-- rainwater_integration
update public.fields set verification_status='verified_against_standard', verification_quote='In all NASS concepts, a straight drainage of rainwater or its separate management is required, which may be limited by existing settlement structures. In any case, a sensible integration of semi-natural rainwater management into the flow-oriented concepts for domestic/municipal wastewater le.g. discharge of rainwater with greywater) is necessary. — printed p.11', verification_note='md-verified 2026-09-05 (§4.2, printed p.11) [VC]', verified_at=now() where id='d621c67e-cd27-4d19-ae94-c12e78adda20' and verification_status not in ('verified_against_standard','corrected');

