update public.fields set verification_status='verified_against_standard', verification_quote='The separate collection of yellow- and brownwater is carried out via urine diverting toilets (gravity or vacuum technology). Conventional urinals can also be used to separate the flow of yellowwater. Blackwater is collected by flushing or vacuum toilets. Collection of urine and faeces is usually carried out by means of urine diverting toilets and waterless urinals. Faeces are only captured via dry toilets. — printed p.12', verification_note='md-verified 2026-09-05 (§4.3 Collection of different material flows, printed p.12) [VC]', verified_at=now() where id='e487d477-9b56-477f-81b9-395248540168' and verification_status not in ('verified_against_standard','corrected');
