-- ######################## A272E-09 Rechtsrahmen-Bewertung ########################
-- legal_WHG_ok
update public.fields set verification_status='verified_against_standard', verification_quote='According to WHG, "Wastewater [...] plants are to be constructed, operated and maintained in such a way that the requirements for wastewater disposal are met. Moreover, sewage plants may only be constructed, operated and maintained in accordance with the generally accepted codes of practice" (§ 60 (1) WHG). — printed p.26', verification_note='md-verified 2026-09-05 (§8 Federal Water Act (WHG), printed p.26) [VC]', verified_at=now() where id='92d2abb7-92cb-4497-a4ea-867d44d37087' and verification_status not in ('verified_against_standard','corrected');
-- legal_Communal_ok
update public.fields set verification_status='verified_against_standard', verification_quote='Another essential point for the implementation of NASS is the clarification of compulsory connection and use. This is stipulated in the statutes for sewage disposal in the municipalities for the respective development area. The compulsory connection is property-related and obliges every property owner within the scope of the statute to connect his property to the local wastewater treatment facilities as soon as wastewater accumulates on the property. — printed p.26', verification_note='md-verified 2026-09-05 (§8 Communal law, printed p.26) [VC]', verified_at=now() where id='18720ed8-84f6-4fc9-aa62-1272d1048e48' and verification_status not in ('verified_against_standard','corrected');
-- legal_BioAbfV_ok
update public.fields set verification_status='verified_against_standard', verification_quote='If bio-waste is involved, for example after the co-fermentation of blackwater and bio-waste, the requirements of the Bio-waste Ordinance (BioAbfV) must be met as well. — printed p.27', verification_note='md-verified 2026-09-05 (§8 Fertilizer Act/Fertilizers Application Ordinance, printed p.27) [VC]', verified_at=now() where id='e108fde0-2b31-402c-97bf-d7d9700345fe' and verification_status not in ('verified_against_standard','corrected');
-- legal_BauGB_ok
update public.fields set verification_status='verified_against_standard', verification_quote='An implementation of NASS can be established in new housing developments using the existing planning and building law with a development plan or a project and development plan. A subsequent change of the development in existing areas cannot be enforced; it can only be approached in cooperation with the property owners and secured in urban development contracts. — printed p.27', verification_note='md-verified 2026-09-05 (§8 Construction Law, printed p.27) [VC]', verified_at=now() where id='6f09f1a6-d961-408f-94f4-d5eb4ba9ed65' and verification_status not in ('verified_against_standard','corrected');
-- legal_DuengG_ok
update public.fields set verification_status='verified_against_standard', verification_quote='NASS produce substrates that can be used as fertilizers. The use of such a product is then subject to the requirements of the fertilizer regulations. Products from NASS are not explicitly mentioned, but depending on their quality they correspond with fertilizers according to § 2 Abs. 1 Fertilizer Act (DüngG). For the application of these substances, the requirements of the Fertilizer Application Ordinance must be met in accordance with § 3 (1) sentence 2 DüngG. — printed p.27', verification_note='md-verified 2026-09-05 (§8 Fertilizer Act/Fertilizers Application Ordinance, printed p.27) [VC]', verified_at=now() where id='85c80228-c15a-435b-ad6d-8c21ba4eb2fe' and verification_status not in ('verified_against_standard','corrected');
-- legal_TrinkwV_ok
update public.fields set verification_status='verified_against_standard', verification_quote='The Drinking Water Ordinance regulates in accordance with European law that a drinking water outlet must be available in every household. However, it does not regulate consumer behaviour, but leaves it to the consumer as to the extent to which he uses water from sources other than the drinking water supply network for his private use. In this respect, the Drinking Water Ordinance is not an inhibiting factor in the implementation of NASS. — printed p.27', verification_note='md-verified 2026-09-05 (§8 Drinking Water Ordinance (TrinkwV), printed p.27) [VC]', verified_at=now() where id='6c08c38f-8fdc-4c1f-9da1-34a9fe4d4493' and verification_status not in ('verified_against_standard','corrected');
-- legal_KrWG_ok
update public.fields set verification_status='verified_against_standard', verification_quote='An essential practical application prerequisite for NASS is the clarification of whether the substance streams or derivatives to be treated are subject to wastewater law or recycling and waste legislation. This also includes the classification of a material as waste, product (e.g.fertilizer) or by-product. — printed p.26', verification_note='md-verified 2026-09-05 (§8 Closed Substance Cycle Waste Management Act (KrWG), printed p.26) [VC]', verified_at=now() where id='9c3f128d-a2a5-485a-8fe2-edb778e9d784' and verification_status not in ('verified_against_standard','corrected');
-- legal_feasibility_overall
update public.fields set verification_status='verified_against_standard', verification_quote='In principle, the recycling of NASS products does not pose any legal obstacles. However, lack of definitions leaves uncertainties for approval. — printed p.27', verification_note='md-verified 2026-09-05 (§8, printed p.27) [VC] — caveat: the feasible/conditional/not_feasible granularity is EKOWAI''s; the source states no verdict scale', verified_at=now() where id='38c6830c-35b0-41b3-9d24-54978d87812e' and verification_status not in ('verified_against_standard','corrected');
-- legal_high_risk_count
update public.fields set verification_status='verified_against_standard', verification_quote='When implementing NASS, there are a large number of regulations, ordinances and technical standards that currently affect the needs of these systems and must therefore be taken into account in planning. The most important regulations include: I Federal Water Act, I Closed Substance Cycle Waste Management Act, I Communal law, I Drinking Water Ordinance, l Construction Law, l Fertilizer Act/Fertilizers Application Ordinance. — printed p.26', verification_note='md-verified 2026-09-05 (§8, printed p.26) [VC]', verified_at=now() where id='e070689f-3038-43e2-938f-67d04a1b7d08' and verification_status not in ('verified_against_standard','corrected');
-- legal_actions_required_count
