-- A272E-07 RULE-7: Q_flush_avg = 33
update public.equations set verification_status='verified_against_standard', verification_quote='Table 5: Comparison of population-specific volume flows and loads | 3) The percentages are given depending on the toilet technology used. In dry toilets no flush water is required and the greywater fraction makes up almost the entire wastewater volume. In case flush toilets are used, the yellow- and brownwater fractions increases and the greywater fraction decreases. The average flushing water requirement is given in BDEW (2011) as $33 \mathrm{l} /(\mathrm{E} \mathrm{d})$. — printed p.21', verification_note='md-verified 2026-09-05 (§6.2 Table 5 footnote 3, printed p.21) [VC] — caveat: the constant 33 l/(E d) is BDEW (2011) as quoted by Table 5', verified_at=now() where id='995ac439-647a-46e2-a23f-9383caa592ed' and verification_status <> 'verified_against_standard';
-- A272E-08 RULE-10: if material_flow_class in {yellowwater,brownwater,blackwater,faeces} then collection_technology in {UDT,UDDT,vacuum_toilet,dry_toilet}
update public.equations set verification_status='verified_against_standard', verification_quote='The separate collection of yellow- and brownwater is carried out via urine diverting toilets (gravity or vacuum technology). Conventional urinals can also be used to separate the flow of yellowwater. Blackwater is collected by flushing or vacuum toilets. Collection of urine and faeces is usually carried out by means of urine diverting toilets and waterless urinals. Faeces are only captured via dry toilets. — printed p.12', verification_note='md-verified 2026-09-05 (§4.3 Collection of different material flows, printed p.12) [VC]', verified_at=now() where id='da12ce07-4e9c-449d-9dd0-c0595dfd0c31' and verification_status <> 'verified_against_standard';
-- A272E-11 RULE-11: treatment_process valid_for (material_flow_class, treatment_objective)
update public.equations set verification_status='verified_against_standard', verification_quote='Table 3: Selected treatment options for different material flows and treatment objective according to the DWA-Topics "New Alternative Sanitation Systems" (DWA 2008) | Material flow & Treatment objective & Possible treatment | Yellowwater/urine & hygienisation & storage | Black- and brownwater & separation/concentration & filtration | Greywater & high-quality service water & biological (membrane) treatment process | Note 1) Suitable for faeces from UDDT systems — printed p.14', verification_note='md-verified 2026-09-05 (§4.3 Table 3, printed p.14) [VC] — caveat: Table 3 is a lookup, not a formula — the equation encodes the admissible (flow x objective x process) triples', verified_at=now() where id='75d8f64a-b888-4752-8b54-391f7cfaca24' and verification_status <> 'verified_against_standard';
